   466→  const bodyRange = blockFieldRanges[bodyIndex];
   467→
   468→  const bodyFieldRanges = BeaconBlockBody.getFieldRanges(
   469→    view,
   470→    messageRange.start + bodyRange.start,
   471→    messageRange.end + bodyRange.end
