   475→  const commitmentSize = KZGCommitment.fixedSize;
   476→
   477→  const end = messageRange.end + bodyRange.end + kzgCommitmentsRange.end;
   478→  const start = messageRange.start + bodyRange.start + kzgCommitmentsRange.start;
   479→
